mapper.select:
SELECT  FROM violation
WHERE user_id = #{userId}
AND status = #{status}
ORDER BY event_at DESC, id DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM violation
WHERE user_id = #{userId}
AND status = #{status}

SELECT v.id, v.reservation_id, v.user_id, v.reason, v.status, v.event_at, v.processed_at,
       v.notified_at, v.deduction_log_id, v.revoked_at, v.revoked_by, v.created_at
FROM violation v
LEFT JOIN app_user u ON u.id = v.user_id

  AND v.status = #{status}
  AND u.account LIKE CONCAT(#{account}, '%')
  AND v.event_at >= #{dateFrom}
  AND v.event_at < DATE_ADD(#{dateTo}, INTERVAL 1 DAY)

ORDER BY v.event_at DESC, v.id DESC
LIMIT #{offset}, #{size}

mapper.update:
UPDATE violation
SET status = 'REVOKED', revoked_at = #{revokedAt}, revoked_by = #{revokedBy}
WHERE id = #{id} AND status = #{expectedStatus}

mapper.select:
SELECT  FROM violation
WHERE notified_at < #{now}
ORDER BY id
